from pathlib import Path
program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, 4, 8):
                points.setdefault(grid[r][c], []).append((r, c))
    # Connect same-colored markers along a diagonal when both lie on it.
    for color, pts in points.items():
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i+1:]:
                dr, dc = r2-r1, c2-c1
                if abs(dr) == abs(dc) and dr != 0:
                    sr = 1 if dr > 0 else -1
                    sc = 1 if dc > 0 else -1
                    for k in range(abs(dr)+1):
                        r, c = r1+sr*k, c1+sc*k
                        if out[r][c] == grid[r][c]:
                            out[r][c] = color
    # A different-colored marker on a connected diagonal sends a line across
    # the grid on the crossing diagonal.
    for color, pts in points.items():
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i+1:]:
                dr, dc = r2-r1, c2-c1
                if abs(dr) != abs(dc) or dr == 0:
                    continue
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                for other, other_pts in points.items():
                    if other == color:
                        continue
                    for r, c in other_pts:
                        t = r-r1
                        if 0 <= t*sr <= abs(dr) and c == c1+sc*(t*sr):
                            # Perpendicular diagonal through (r,c), to both edges.
                            for rr in range(h):
                                cc = c-(rr-r)
                                if 0 <= cc < w and out[rr][cc] == grid[rr][cc]:
                                    out[rr][cc] = other
    return out
'''
